SLUGS=['product']+[m[0] for m in DATA['en']['modules']]+['solutions/ai-readiness']

def configure(copy):
 for lang,t in copy.items():
  x=DATA[lang]
  from expansion import D,SLUGS as EXP
  for i,name in enumerate(D[lang]['names']):
   t['labels'][EXP[i+1]]=name;t['navDesc'][EXP[i+1]]=D[lang]['leads'][i]
  for slug,label,_,lead,_ in x['modules']:
   t['labels'][slug]=label;t['navDesc'][slug]={'en':['Customer access, documents and requests','API connections and synchronisation','Reliable indicators and clear next actions','Approved knowledge with source references'],'nl':['Klanttoegang, documenten en aanvragen','API-koppelingen en synchronisatie','Betrouwbare cijfers en duidelijke acties','Goedgekeurde kennis met bronverwijzingen'],'fr':['Accès clients, documents et demandes','Connexions API et synchronisation','Indicateurs fiables et actions claires','Connaissances approuvées et références']}[lang][[m[0] for m in x['modules']].index(slug)]
  for slug,label,desc in [('product',x['product'],x['intro']),('solutions/ai-readiness',x['ready'],x['readyLead'])]:
   t['labels'][slug]=label;t['navDesc'][slug]=desc
  t['navGroups']=[dict(label=x['product'],overview='product',intro=x['intro'],keys=['ai-infrastructuur','solutions/custom-crm','product/customer-portals','product/knowledge-assistants','product/integrations','product/dashboards']),dict(label=x['solutions'],overview='solutions',intro=x['solutionLead'],keys=['solutions/ai-readiness','solutions/document-processing','solutions/sales-operations','solutions/customer-support','solutions/technical-operations']),dict(label=x['expertise'],overview='diensten',intro={'en':'Engineering around your existing business.','nl':'Techniek rond jouw organisatie.','fr':'L’ingénierie autour de votre activité.'}[lang],keys=['managed-it','cloud','security','development','websites','webshop','branding','games']),dict(label=x['company'],overview='over-ons',intro={'en':'Meet Marleo. Plan your next project.','nl':'Ontdek Marleo. Plan je volgende project.','fr':'Découvrir Marleo. Préparer votre projet.'}[lang],keys=['over-ons','security-deployment','prijzen','contact'])]
  t['footer'].insert(0,dict(head=x['product'],keys=['product','product/knowledge-assistants','product/customer-portals','product/integrations','product/dashboards','solutions/ai-readiness']))

def cards(lang,g,items):
 return '<div class="catalog-cards">'+''.join('<a class="catalog-card" href="%s"><span class="eyebrow">%02d</span><h3>%s</h3><p>%s</p><span class="eu-link">%s %s</span></a>'%(g['url'](lang,s),i+1,e(n),e(b),e(DATA[lang]['more']),g['ARROW']) for i,(s,n,b) in enumerate(items))+'</div>'

def home_products(lang,g):
 x=DATA[lang]
 items=[('ai-infrastructuur',g['COPY'][lang]['labels']['ai-infrastructuur'],g['EU_TEXT'][lang]['services'][0][1]),('solutions/custom-crm',g['COPY'][lang]['labels']['solutions/custom-crm'],g['EU_TEXT'][lang]['services'][1][1])]+[(m[0],m[1],m[3]) for m in x['modules']]
 return '<section class="sec catalog-home" id="product"><div class="wrap"><div class="catalog-heading"><div><span class="eyebrow">%s</span><h2>%s</h2></div><a class="eu-link" href="%s">%s %s</a></div>%s</div></section>'%(e(x['product']),e(x['intro']),g['url'](lang,'product'),e(x['overview']),g['ARROW'],cards(lang,g,items)+'<a class="catalog-readiness" href="'+g['url'](lang,'solutions/ai-readiness')+'"><span class="eyebrow">AI / STRATEGY</span><h3>'+e(x['ready'])+'</h3><p>'+e(x['readyLead'])+'</p><span class="eu-link">'+e(x['more'])+g['ARROW']+'</span></a>')

def render(lang,slug,g):
 x=DATA[lang];u=g['url']
 if slug=='product': title=x['intro'];lead=x['lead'];items=None
 elif slug=='solutions': title=x['solutions'];lead=x['solutionLead'];items=None
 elif slug=='solutions/ai-readiness':title=x['ready'];lead=x['readyLead'];items=x['readyItems']
 else: _,label,title,lead,items=next(m for m in x['modules'] if m[0]==slug)
 body=g['phero'](lang,slug,x['solutions'] if slug.startswith('solutions') else x['product'],title,lead,acts=False)
 if slug=='product':
  body+=home_products(lang,g)
  body+='<section class="sec catalog-delivery" id="delivery"><div class="wrap"><span class="eyebrow">MARLEO / DELIVERY</span><h2>'+e(x['delivery'])+'</h2><div class="eu-steps">'+''.join('<article><span>%02d</span><h3>%s</h3><p>%s</p></article>'%(i+1,e(a),e(b)) for i,(a,b) in enumerate(x['stages']))+'</div></div></section>'
 elif slug=='solutions':
  from expansion import D,SLUGS as EXP
  d=D[lang];rows=[('solutions/ai-readiness',x['ready'],x['readyLead'])]+[(EXP[i+1],n,d['leads'][i]) for i,n in enumerate(d['names'])]
  body+='<section class="sec"><div class="wrap">'+cards(lang,g,rows)+'</div></section>'+g['system_showcase'](lang,u)
 else:
  body+='<section class="sec"><div class="wrap catalog-detail"><div class="catalog-detail-intro"><span class="eyebrow">'+e(x['built'])+'</span><h2>'+e(x['flow'])+'</h2><div class="catalog-flow" aria-hidden="true">'+''.join('<span>'+e(s)+'</span>' for s in (x['input'],x['process'],x['output']))+'</div></div><div class="catalog-detail-steps">'+''.join('<article><span class="eu-index">%02d</span><div><h2>%s</h2><p>%s</p></div></article>'%(i+1,e(a),e(b)) for i,(a,b) in enumerate(items))+'</div></div></section>'
 body+='<section class="sec catalog-controls"><div class="wrap split"><div><span class="eyebrow">MARLEO / CONTROL</span><h2>'+e(x['control'])+'</h2></div><div><p class="lead">'+e(x['controlBody'])+'</p><p class="catalog-note">'+e(x['scope'])+'</p><a class="eu-link" href="'+u(lang,'security-deployment')+'">'+e(g['COPY'][lang]['labels']['security-deployment'])+g['ARROW']+'</a></div></div></section><section class="sec"><div class="wrap"><a class="btn btn-p" href="'+u(lang,'project-intake')+'">'+e(x['next'])+g['ARROW']+'</a></div></section>'
 return g['page'](lang,slug,title+' | Marleo',lead[:175],body)
